import {n,POS,REQUIRED,money,sellingPrice,fixturesFor,opponent,enrich,bestLineup,validateSquad,transferIdeas,priceSignal,chipAdvice} from '/model.mjs';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=1)=>n(v).toLocaleString('en-GB',{minimumFractionDigits:d,maximumFractionDigits:d});
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',shirt:'m8 3-5 3 3 5 2-1v11h8V10l2 1 3-5-5-3c-1 3-7 3-8 0Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Z M8 14h2 M14 14h2 M8 18h2',arrows:'M4 7h15l-4-4 M20 17H5l4 4 M20 7l-5 4 M4 17l5-4',trend:'m3 17 6-6 4 4 8-10 M15 5h6v6',chip:'M8 3h8l5 9-5 9H8l-5-9Z M9 9h6v6H9z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z M20 2v4 M18 4h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',arrow:'M19 12H5 M11 6l-6 6 6 6',chevron:'m14 6-6 6 6 6',refresh:'M20 7v5h-5 M4 17v-5h5 M6 6a8 8 0 0 1 13 2 M18 18A8 8 0 0 1 5 16',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',wallet:'M3 6h17v15H3V6Zm0 0 14-3v3 M16 12h5v5h-5z',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',check:'m5 12 4 4L19 6',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'m12 3 9 4v5c0 6-9 10-9 10S3 18 3 12V7Z m-4 9 3 3 5-6',menu:'M3 6h18 M3 12h18 M3 18h18',close:'m6 6 12 12 M6 18 18 6',send:'m22 2-7 20-4-9-9-4Z M22 2 11 13',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',link:'m10 13 4-4 M8 16l-2 2a3 3 0 0 1-4-4l4-4a3 3 0 0 1 4 0 M14 8l2-2a3 3 0 0 1 4 4l-4 4a3 3 0 0 1-4 0',book:'M12 5c-4-3-9-2-9-2v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2Z M12 5v16',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',plus:'M12 5v14 M5 12h14',trophy:'M8 3h8v8a4 4 0 0 1-8 0V3Z M8 5H3v3a4 4 0 0 0 5 4 M16 5h5v3a4 4 0 0 1-5 4 M12 15v6 M8 21h8'};
const icon=(key,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[key]||icons.spark}"/></svg>`;
let stored={};try{stored=JSON.parse(localStorage.getItem('madar-fpl-v1')||'{}');}catch{}
let settings={gw:11,budget:1000,ft:1,bank:0,risk:'balanced',goal:'تكوين فريق قوي للموسم',isNew:true,purchases:{},chips:{wildcard:true,freehit:true,bboost:true,'3xc':true},...stored.settings};
settings.purchases||={};settings.chips||={};
let data=null,players=[],squadIds=Array.isArray(stored.squad)?stored.squad:[],page=(location.hash.slice(1)||'dashboard').split('?')[0],busy=false,refreshing=false,chat=[],priceTab='in';
let playerFilter={search:'',pos:0,sort:'score',max:20,page:1};
const historyTimes={};let openPlayerId=null;
const nav=[['dashboard','grid','لوحة القيادة'],['squad','shirt','تشكيلتي'],['transfers','arrows','الانتقالات'],['players','users','مستكشف اللاعبين'],['fixtures','calendar','جدول المباريات'],['prices','trend','الأسعار والميزانية'],['chips','chip','خطة الرقاقات'],['advisor','spark','المساعد التحليلي']];
function persist(){try{localStorage.setItem('madar-fpl-v1',JSON.stringify({settings,squad:squadIds}));}catch{toast('المتصفح لا يسمح بالحفظ المحلي. يمكنك تنزيل خطتك.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function team(p){return data.teams.find(t=>t.id===p.team);}
function squad(){return squadIds.map(id=>players.find(p=>p.id===id)).filter(Boolean);}
function bank(){return settings.isNew?settings.budget-squad().reduce((s,p)=>s+p.now_cost,0):settings.bank;}
function lineup(){return bestLineup(squad());}
function recompute(){players=enrich(data,n(settings.gw),5,settings.risk);squadIds=squadIds.filter(id=>players.some(p=>p.id===id));}
async function updateHistories(ids){
 const pending=[...new Set(ids)].filter(id=>Date.now()-(historyTimes[id]||Date.parse(data.meta.historyFetchedAt)||0)>10800000);
 let failures=0,changed=false;
 for(let i=0;i<pending.length;i+=6){
  const results=await Promise.allSettled(pending.slice(i,i+6).map(async id=>{const r=await fetch(`/api/history/${id}`);if(!r.ok)throw new Error();const result=await r.json();if(!Array.isArray(result.history))throw new Error();return [id,result.history];}));
  for(const result of results)if(result.status==='fulfilled'){const [id,history]=result.value;data.histories[id]=history;historyTimes[id]=Date.now();changed=true;}else failures++;
 }
 if(changed){recompute();try{const cached={season:season(),histories:Object.fromEntries(Object.keys(historyTimes).slice(-120).map(id=>[id,{time:historyTimes[id],history:data.histories[id]}]))};localStorage.setItem('madar-history-v1',JSON.stringify(cached));}catch{}}
 return {changed,failures};
}
function nextEvent(){return data.events.find(e=>e.is_next)||data.events.find(e=>!e.finished)||data.events.at(-1);}
function currentEvent(){return data.events.find(e=>e.id===n(settings.gw));}
function dateText(iso,withTime=true){if(!iso)return 'غير محدد';return new Intl.DateTimeFormat('ar-EG',{timeZone:'Etc/GMT-3',day:'numeric',month:'long',...(withTime?{hour:'2-digit',minute:'2-digit',hour12:false}:{})}).format(new Date(iso));}
function season(){const year=new Date(data.events[0].deadline_time).getUTCFullYear();return `${year}/${String(year+1).slice(2)}`;}
function fixtureLabel(p,gw=settings.gw){return fixturesFor(data,p.team,n(gw)).map(f=>{const op=opponent(data,f,p.team);return `${op.team.short_name} (${op.home?'H':'A'})`;}).join(' + ')||'لا مباراة';}
const shirtColors={ARS:['#e6494d','#fff'],AVL:['#7d324c','#83bde2'],BOU:['#cb3c44','#101a24'],BRE:['#e7464a','#fff'],BHA:['#3a7dc8','#fff'],BUR:['#7d364b','#92bed7'],CHE:['#3d68cc','#e1eaff'],CRY:['#3866bd','#c53b56'],EVE:['#3370c7','#fff'],FUL:['#edf0ee','#1d2933'],LEE:['#e5ebdf','#e5c644'],LIV:['#d14345','#edebd4'],MCI:['#86cce3','#284654'],MUN:['#dc494a','#f7e9d9'],NEW:['#d8dfdf','#29333c'],NFO:['#e4554e','#fff'],SUN:['#e14d53','#e4e5e3'],TOT:['#e7ecea','#22334f'],WHU:['#843e58','#8ab7cc'],WOL:['#e6b24d','#17232a']};
function shirt(p,cls='shirt'){const c=shirtColors[team(p)?.short_name]||['#9ab6c5','#e9f0e9'];const main=p.element_type===1?'#c5bb68':c[0];const trim=p.element_type===1?'#494a2e':c[1];return `<svg class="${cls}" viewBox="0 0 52 54" aria-hidden="true"><path d="M17 4 4 12l6 13 7-4v29h18V21l7 4 6-13-13-8c-2 5-16 5-18 0Z" fill="${main}" stroke="#ffffff33" stroke-width=".7"/><path d="m17 4 3 8h12l3-8c-4 4-14 4-18 0Z" fill="${trim}"/><path d="m4 12 6 13 3-2-6-13ZM45 10l-6 13 3 2 6-13Z" fill="${trim}" opacity=".8"/><path d="M18 47h16" stroke="#0002" stroke-width="2"/></svg>`;}
function playerOnPitch(p,l,bench=false){return `<button class="pitch-player" data-player="${p.id}" aria-label="تحليل ${esc(p.web_name)}، ${fmt(p.xp)} نقطة متوقعة"><span class="shirt-wrap">${shirt(p)}<span class="shirt-number" style="--shirt-text:${(shirtColors[team(p)?.short_name]||[])[1]||'#fff'}">${p.squad_number||''}</span>${!bench&&p.id===l.captain?.id?'<span class="captain-badge">C</span>':!bench&&p.id===l.vice?.id?'<span class="captain-badge vice">V</span>':''}</span><span class="player-name">${esc(p.web_name)}</span><span class="player-fixture">${esc(fixtureLabel(p))}</span><span class="player-xp">${fmt(p.xp)} xPts</span></button>`;}
function pitch(full=false){const l=lineup();return `<div class="pitch-container"><div class="pitch">${l.starters.length?`<div class="pitch-lines"><div class="center-circle"></div><div class="penalty-area top"><div class="six-yard"></div></div><div class="penalty-area bottom"><div class="six-yard"></div></div></div>${[1,2,3,4].map(pos=>`<div class="pitch-row">${l.starters.filter(p=>p.element_type===pos).map(p=>playerOnPitch(p,l)).join('')}</div>`).join('')}`:`<div class="empty-pitch">${busy?'<span class="spinner"></span>':icon('shirt',35)}<p>${busy?'نوازن الأرقام والميزانية لاختيار فريقك…':'مساحتك لبدء فريق جديد'}</p>${!busy?'<button class="button primary" data-action="generate">ابنِ فريقي الآن</button>':''}</div>`}</div><div class="pitch-caption"><span>${icon('info',11)} النقاط تقديرات، وتشمل مضاعفة الكابتن في الإجمالي</span><span class="num">${l.formation}</span></div>${l.bench.length?`<div class="bench-header"><span>دكة البدلاء · ترتيب مقترح</span><span><span class="num">${fmt(l.bench.reduce((s,p)=>s+p.xp,0))}</span> نقطة متوقعة</span></div><div class="bench">${l.bench.map(p=>playerOnPitch(p,l,true)).join('')}</div>`:''}<div class="squad-note">${icon('shield',13)} ${settings.isNew?'تشكيلة البداية مجانية. احفظ اختياراتك داخل حساب FPL قبل الموعد.':'هذه مسودة محلية؛ طبّق التغييرات بنفسك في حساب FPL.'}</div></div>`;}
function fixtureRun(p,count=5){return `<div class="fixture-run">${Array.from({length:count},(_,i)=>{const fs=fixturesFor(data,p.team,n(settings.gw)+i);return fs.length?fs.map(f=>{const op=opponent(data,f,p.team);return `<span class="fixture-tag fdr${op.fdr}" title="الجولة ${n(settings.gw)+i}، الصعوبة ${op.fdr}">${op.team.short_name}<small> ${op.home?'H':'A'}</small></span>`;}).join(''):'<span class="fixture-tag">—</span>';}).join('')}</div>`;}
function playerCell(p){return `<button class="name-button table-player" data-player="${p.id}">${shirt(p,'table-shirt')}<span><strong>${esc(p.web_name)}</strong><small>${esc(team(p)?.short_name)} · ${POS[p.element_type]}</small></span></button>`;}
function heading(title,sub,actions='',eyebrow=''){return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow"><i class="dot"></i>${eyebrow}</div>`:''}<h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function footer(){return `<footer class="site-footer"><span><span class="footer-brand">مَدار</span> &nbsp; قرارك القادم يبدأ من البيانات.</span><span>المصدر: <a href="https://fantasy.premierleague.com" target="_blank" rel="noopener">FPL الرسمي</a> · <a href="#method">منهجية التحليل</a> · تطبيق مستقل</span></footer>`;}
function render(){
 if(!data)return;
 if(![...nav.map(x=>x[0]),'settings','method'].includes(page))page='dashboard';
 const title=nav.find(x=>x[0]===page)?.[2]||({settings:'إعدادات الفريق',method:'منهجية التحليل'}[page]);
 const views={dashboard:dashboardView,squad:squadView,transfers:transfersView,players:playersView,fixtures:fixturesView,prices:pricesView,chips:chipsView,advisor:advisorView,settings:settingsView,method:methodView};
 $('#app').innerHTML=`<div class="mobile-overlay" data-action="close-menu"></div><aside class="sidebar"><a class="brand" href="#dashboard"><span class="brand-symbol">${icon('target',28)}</span><span><span class="brand-title">مَدار</span><span class="brand-sub">FPL ADVISOR</span></span></a><div class="nav-label">مساحتك في الفانتزي</div><nav class="nav" aria-label="القائمة الرئيسية">${nav.map(([key,ic,label])=>`<a href="#${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(ic,18)}<span>${label}</span>${key==='advisor'?'<span class="nav-count">اسأل</span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('spark',21)}<strong>كل قرار، له أرقامه.</strong><p>مؤشرات متقدمة. توصيات مفسّرة.<br>ومساحة أكبر لحدسك الكروي.</p></div><nav class="nav"><a href="#settings" class="${page==='settings'?'active':''}">${icon('settings',17)}إعدادات الفريق</a><a href="#method" class="${page==='method'?'active':''}">${icon('book',17)}دليل الأرقام</a></nav><div class="sidebar-user"><span class="avatar">${icon('users',16)}</span><div class="user-info"><strong>${settings.isNew?'مدرب جديد':'مدرب الفانتزي'}</strong><span>${esc(settings.goal||'خطّط لجولتك القادمة')}</span></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs"><button class="icon-button mobile-menu" data-action="menu" aria-label="افتح القائمة">${icon('menu',17)}</button><span>مساحة المدرب</span>${icon('chevron',11)}<span class="current">${title}</span></div><div class="top-actions"><span class="live-badge ${data.meta.live?'':'stale'}">${data.meta.live?'بيانات رسمية محدثة':'نسخة بيانات محفوظة'}</span><span class="season-tag">الموسم <span class="num">${season()}</span></span><button class="icon-button" data-action="install" title="تثبيت مَدار على جهازك" aria-label="تثبيت مَدار على جهازك">${icon('download',15)}</button><button class="icon-button" data-action="refresh" title="تحديث البيانات" aria-label="تحديث البيانات" ${refreshing?'disabled':''}>${refreshing?'<span class="spinner"></span>':icon('refresh',15)}</button></div></header><main class="main" id="main">${views[page]()}${footer()}</main></div>`;
}
function stats(){const s=squad(),l=lineup(),cost=s.reduce((a,p)=>a+p.now_cost,0);return `<div class="stats-grid"><div class="stat-card highlight"><div class="stat-head"><span>النقاط المتوقعة</span>${icon('target',17)}</div><div class="stat-value"><span class="num">${s.length?fmt(l.points):'—'}</span><span class="unit">نقطة</span></div><div class="stat-foot"><span class="green">شامل الكابتن</span><span>· الجولة ${settings.gw}</span></div><svg class="stat-spark" width="67" height="23" viewBox="0 0 67 23"><path d="m1 20 11-6 10 4 9-11 10 4 11-8 14-2" fill="none" stroke="#c2f76a" stroke-width="1.5"/></svg></div><div class="stat-card"><div class="stat-head"><span>المتبقي في البنك</span>${icon('wallet',17)}</div><div class="stat-value"><span class="num">${money(bank())}</span></div><div class="stat-foot">${settings.isNew?`من ميزانية <span class="num">${money(settings.budget)}</span>`:'محسوب وفق أسعار البيع المسجلة'}</div></div><div class="stat-card"><div class="stat-head"><span>النقلات الحرة</span>${icon('arrows',17)}</div><div class="stat-value">${settings.isNew?'<span>تأسيس مجاني</span>':`<span class="num">${settings.ft}</span><span class="unit">نقلة</span>`}</div><div class="stat-foot">${settings.isNew?'اختر 15 لاعبًا دون خصم نقاط':'4 نقاط لكل نقلة إضافية'}</div></div><div class="stat-card"><div class="stat-head"><span>قيمة التشكيلة</span>${icon('shirt',17)}</div><div class="stat-value"><span class="num">${money(cost)}</span></div><div class="stat-foot"><span class="green num">${s.length}/15</span><span>لاعبًا في مسودتك</span></div></div></div>`;}
function deadlineStrip(){const e=currentEvent();const outdated=e?.finished||new Date(e?.deadline_time).getTime()<Date.now();return `<div class="status-strip ${outdated||!data.meta.live?'warn':''}">${icon('clock',15)}<span>${outdated?'انتهى موعد الجولة المختارة. عدّل الجولة من الإعدادات.':`آخر موعد للجولة ${settings.gw}: <strong>${dateText(e?.deadline_time)}</strong> <span class="muted">(UTC+3)</span>`}</span><a class="strip-link" href="#settings">تعديل خطة البداية ${icon('arrow',12)}</a></div>${!data.meta.live?`<div class="notice warn mb">تعذر الاتصال المباشر بالمصدر. الأرقام من نسخة محفوظة بتاريخ ${dateText(data.meta.fetchedAt)} (UTC+3). حدّثها قبل اتخاذ قرار.</div>`:''}`;}
function captainCard(){const p=lineup().captain;if(!p)return '';return `<section class="panel captain-panel"><div class="panel-head"><h2>شارة القيادة</h2><span class="pill green-pill">${icon('spark',12)} ترشيح مَدار</span></div><div class="captain-content"><div class="captain-avatar">${shirt(p)}<span class="captain-badge">C</span></div><div><div class="captain-name">${esc(p.web_name)}</div><div class="captain-meta">${esc(team(p).name)} · ${esc(fixtureLabel(p))}</div><div class="confidence mt" style="margin-top:8px"><i></i>${p.chance===1?'متاح وفق آخر تحديث':'يتطلب متابعة أخبار المشاركة'}</div></div></div><div class="captain-numbers"><div><strong class="green">${fmt(p.xp)}</strong><span>نقاط متوقعة قبل المضاعفة</span></div><div><strong>${fmt(p.recent.xg90+p.recent.xa90,2)}</strong><span>xGI لكل 90 دقيقة</span></div><div><strong>${fmt(p.selected_by_percent)}%</strong><span>الملكية العامة</span></div></div><p class="captain-reason">أعلى xGI متوقع بين أساسيي فريقك الموثوقين بالدقائق، بعد تعديل قوة الخصم. النائب: <strong>${esc(lineup().vice?.web_name||'—')}</strong>.</p></section>`;}
function insights(){const s=squad(),risky=s.filter(p=>p.chance<1||p.recent.avgMinutes<60),value=[...s].sort((a,b)=>b.ppm-a.ppm)[0];return `<section class="panel"><div class="panel-head"><h2>قراءة سريعة للجولة</h2>${icon('spark',16)}</div><div class="insight-list"><div class="insight"><span class="insight-icon">${icon('shield',15)}</span><div><strong>${risky.length?`${risky.length} لاعبين يحتاجون إلى متابعة`:'تشكيلتك جاهزة مبدئيًا'}</strong><p>${risky.length?esc(risky.map(p=>p.web_name).join('، '))+' — راجع المشاركة قبل الإغلاق.':'أعد فحص أخبار الإصابات والمؤتمرات قبل تثبيت اختياراتك.'}</p></div></div><div class="insight"><span class="insight-icon yellow-bg">${icon('clock',15)}</span><div><strong>لا تستعجل النقلة المبكرة</strong><p>انتظر أخبار المنتخب والمؤتمرات، إلا إذا كانت زيادة السعر ستغلق ميزانيتك.</p></div></div><div class="insight"><span class="insight-icon blue-bg">${icon('trend',15)}</span><div><strong>${value?`${esc(value.web_name)} يقدم قيمة جيدة`:'انطلق من الميزانية'}</strong><p>${value?`حقق ${fmt(value.ppm)} نقطة لكل مليون خلال الموسم. راجع المباريات المقبلة قبل الشراء.`:'وزّع ميزانيتك بين أساسيين موثوقين ودكة قابلة للمشاركة.'}</p></div></div></div></section>`;}
function dashboardView(){const candidates=[...players].filter(p=>p.chance>=.75&&p.recent.avgMinutes>55).sort((a,b)=>b.score-a.score);const top=[1,2,3,4].map(pos=>candidates.find(p=>p.element_type===pos)).filter(Boolean);return `${heading('جولتك القادمة، برؤية أوضح.','تشكيلتك، فرصك، وقرارك القادم. كل ما تحتاجه في مكان واحد.',`<a href="#settings" class="button ghost">${icon('settings',14)} إعدادات البداية</a><button class="button primary" data-action="generate" ${busy?'disabled':''}>${busy?'<span class="spinner"></span>':icon('spark',15)} ${squadIds.length?'أعد بناء التشكيلة':'ابنِ فريقي'}</button>`,`الجولة ${settings.gw} · ${settings.isNew?'بداية جديدة':'خطة فريقك'}`)}${deadlineStrip()}${stats()}<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>التشكيلة المقترحة</h2><p>توازن بين جودة الفرص والمباريات الخمس المقبلة</p></div><span class="pill"><span class="num">${lineup().formation}</span></span></div>${pitch()}</section><div class="side-stack">${captainCard()}${insights()}<a class="advisor-cta" href="#advisor"><span class="cta-icon">${icon('spark',21)}</span><div><strong>اسأل قبل أن تحسم قرارك.</strong><p>مستشارك يعرف أرقام فريقك.</p></div><span class="green">${icon('arrow',18)}</span></a></div></div><section class="panel section-gap"><div class="panel-head"><div><h2>تحت الرادار</h2><p>خيارات تستحق المتابعة، مركزًا بمركز</p></div><a class="text-link" href="#players">استكشف اللاعبين ${icon('arrow',13)}</a></div><div class="table-wrap"><table><thead><tr><th>اللاعب</th><th>السعر</th><th>xGI / 90</th><th>الملكية</th><th>الجولات المقبلة</th><th>xPts</th></tr></thead><tbody>${top.map(p=>`<tr><td>${playerCell(p)}</td><td class="metric">${money(p.now_cost)}</td><td class="metric">${fmt(p.recent.xg90+p.recent.xa90,2)}</td><td class="metric">${fmt(p.selected_by_percent)}%</td><td>${fixtureRun(p,3)}</td><td><span class="metric-pill">${fmt(p.xp)}</span></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>xGI = الأهداف المتوقعة + التمريرات الحاسمة المتوقعة</span>${fdrLegend()}</div></section><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>حركة السوق</h2><a class="text-link" href="#prices">التفاصيل ${icon('arrow',12)}</a></div><div class="panel-body">${priceRows(3)}<p class="help mt">تدفقات الجولة تشير إلى اتجاه الطلب؛ لا تضمن ارتفاعًا بمقدار £0.1m.</p></div></section><section class="panel"><div class="panel-head"><h2>رقاقاتك، في وقتها.</h2><a class="text-link" href="#chips">الخطة ${icon('arrow',12)}</a></div><div class="panel-body">${chipAdvice(data,squad(),n(settings.gw),settings.isNew,settings.chips).slice(0,3).map(c=>`<div class="chip-mini"><span class="chip-icon">${icon('chip',17)}</span><div><strong>${c.name}</strong><small>${c.available?`النافذة الحالية حتى الجولة ${c.stop}`:'راجع نافذة الاستخدام'}</small></div><span class="pill ${c.available?'green-pill':''}">${c.status}</span></div>`).join('')}</div></section></div>`;}
function fdrLegend(){return '<div class="legend"><span><i></i> أسهل</span><span><i class="medium"></i> متوسط</span><span><i class="hard"></i> أصعب</span></div>';}
function squadView(){const s=squad(),l=lineup(),errors=s.length?validateSquad(s,settings.isNew?settings.budget:s.reduce((a,p)=>a+p.now_cost,0)+bank()):[];return `${heading('فريقك، من أول قرار.','ابدأ بمقترح مبني على البيانات، ثم عدّله حسب رؤيتك.',`<button class="button" data-action="export">${icon('download',14)} تنزيل الخطة</button><button class="button primary" data-action="generate" ${busy?'disabled':''}>${busy?'<span class="spinner"></span>':icon('spark',14)} بناء تشكيلة</button>`)}${deadlineStrip()}${errors.length?`<div class="notice error mb">${errors.map(esc).join(' · ')}</div>`:''}<div class="two-column"><section class="panel"><div class="panel-head"><h2>الجولة ${settings.gw}</h2><span class="pill green-pill">${s.length?fmt(l.points)+' نقطة متوقعة':'مسودة جديدة'}</span></div>${pitch(true)}</section><div class="stack"><section class="panel"><div class="panel-head"><h2>خيارات البداية</h2>${icon('settings',17)}</div><div class="panel-body"><form id="start-form" class="form-grid"><label class="form-field">ميزانية التشكيلة (£m)<input name="budget" type="number" min="65" max="200" step="0.1" value="${settings.budget/10}" required></label><label class="form-field">الجولة المستهدفة<select name="gw">${gwOptions()}</select></label><label class="form-field full">أسلوب اللعب<select name="risk">${riskOptions()}</select></label><button type="submit" class="button primary form-field full">احفظ الإعدادات وابنِ فريقي</button></form><p class="help mt">فريق جديد رسميًا يبدأ بميزانية £100m. تعديلها يفيد عند إعادة بناء فريق ذي قيمة مختلفة.</p></div></section>${captainCard()}<section class="panel"><div class="panel-head"><h2>قبل صافرة البداية</h2></div><div class="panel-body"><ul class="checklist"><li>${icon('check',14)} 2 حراس، 5 دفاع، 5 وسط، 3 هجوم.</li><li>${icon('check',14)} ثلاثة لاعبين كحد أقصى من كل نادٍ.</li><li>${icon('check',14)} اختيار الكابتن والنائب وترتيب الدكة.</li><li>${icon('check',14)} افتح حسابك في FPL وسجّل اختياراتك.</li></ul><a href="https://fantasy.premierleague.com" target="_blank" rel="noopener" class="button ghost mt">افتح FPL ${icon('link',13)}</a></div></section></div></div><section class="panel section-gap"><div class="panel-head"><h2>تفاصيل التشكيلة</h2><span class="small muted">اضغط على لاعب لتفاصيله أو استبداله</span></div><div class="table-wrap"><table><thead><tr><th>اللاعب</th><th>السعر الحالي</th><th>متوسط الدقائق</th><th>xG</th><th>xA</th><th>حالة المشاركة</th><th>xPts</th><th>التعديل</th></tr></thead><tbody>${s.sort((a,b)=>a.element_type-b.element_type||b.xp-a.xp).map(p=>`<tr><td>${playerCell(p)}</td><td class="metric">${money(p.now_cost)}</td><td class="metric">${fmt(p.recent.avgMinutes,0)}</td><td class="metric">${fmt(p.recent.xg,2)}</td><td class="metric">${fmt(p.recent.xa,2)}</td><td><span class="pill ${p.chance===1?'green-pill':'warn-pill'}">${p.chance===1?'متاح':fmt(p.chance*100,0)+'%'}</span></td><td><span class="metric-pill">${fmt(p.xp)}</span></td><td><button class="text-link" data-action="swap" data-id="${p.id}">استبدال ${icon('arrows',12)}</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">ابنِ فريقك لإظهار التفاصيل.</td></tr>'}</tbody></table></div><div class="table-footer">xG وxA بحسب نافذة كل لاعب: آخر 5 مباريات متاحة، أو الموسم عند غياب التاريخ التفصيلي.</div></section>`;}
function gwOptions(){return data.events.filter(e=>e.id>=Math.min(11,nextEvent().id)||e.id===n(settings.gw)).map(e=>`<option value="${e.id}" ${e.id===n(settings.gw)?'selected':''}>الجولة ${e.id}${e.is_next?' · المقبلة':''}</option>`).join('');}
function riskOptions(){return [['balanced','متوازن · أفضل مجموع متوقع'],['protect','حماية الترتيب · ميل للخيارات الشائعة'],['chase','مطاردة الترتيب · ميل للخيارات المختلفة']].map(([v,t])=>`<option value="${v}" ${settings.risk===v?'selected':''}>${t}</option>`).join('');}
function playersView(){const f=playerFilter;let list=players.filter(p=>!p.removed&&(f.pos===0||p.element_type===f.pos)&&p.now_cost<=f.max*10&&(`${p.web_name} ${p.first_name} ${p.second_name} ${team(p)?.name} ${team(p)?.short_name}`).toLowerCase().includes(f.search.toLowerCase()));list.sort((a,b)=>f.sort==='cost'?a.now_cost-b.now_cost:f.sort==='ownership'?n(b.selected_by_percent)-n(a.selected_by_percent):f.sort==='xgi'?b.recent.xg90+b.recent.xa90-a.recent.xg90-a.recent.xa90:f.sort==='value'?b.ppm-a.ppm:b.score-a.score);const count=list.length, pages=Math.max(1,Math.ceil(count/20));f.page=Math.min(f.page,pages);list=list.slice((f.page-1)*20,f.page*20);return `${heading('اقرأ ما وراء النقاط.','قارن جودة الفرص، دقائق المشاركة، والمباريات قبل أن تختار.')}<section class="panel"><div class="panel-head"><h2>مستكشف اللاعبين</h2><span class="pill num">${count} لاعبًا</span></div><div class="filters"><input id="player-search" aria-label="ابحث عن لاعب أو نادٍ" placeholder="ابحث باسم اللاعب أو النادي بالإنجليزية…" value="${esc(f.search)}"><select id="player-pos" aria-label="المركز"><option value="0">كل المراكز</option>${Object.entries(POS).map(([k,v])=>`<option value="${k}" ${n(k)===f.pos?'selected':''}>${v}</option>`).join('')}</select><select id="player-sort" aria-label="ترتيب اللاعبين">${[['score','ترشيح مَدار'],['xgi','أعلى xGI / 90'],['value','النقاط لكل مليون'],['ownership','نسبة الملكية'],['cost','الأقل سعرًا']].map(([k,v])=>`<option value="${k}" ${f.sort===k?'selected':''}>${v}</option>`).join('')}</select><select id="player-max" aria-label="أقصى سعر">${[5,6,7,8,10,12,16,20].map(v=>`<option value="${v}" ${v===f.max?'selected':''}>حتى £${v}m</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>اللاعب</th><th>السعر</th><th>xG / 90</th><th>xA / 90</th><th>xGI / 90</th><th>دقائق/مباراة</th><th>الملكية</th><th>نقطة/مليون</th><th>الجولات الخمس</th><th>xPts</th></tr></thead><tbody>${list.map(p=>`<tr><td>${playerCell(p)}${p.status!=='a'?'<span class="tiny yellow">'+esc(p.news||'غير متاح بالكامل')+'</span>':''}</td><td class="metric">${money(p.now_cost)}</td><td class="metric">${fmt(p.recent.xg90,2)}</td><td class="metric">${fmt(p.recent.xa90,2)}</td><td class="metric green">${fmt(p.recent.xg90+p.recent.xa90,2)}</td><td class="metric">${fmt(p.recent.avgMinutes,0)}</td><td class="metric">${fmt(p.selected_by_percent)}%</td><td class="metric">${fmt(p.ppm)}</td><td>${fixtureRun(p)}</td><td><span class="metric-pill">${fmt(p.xp)}</span></td></tr>`).join('')||'<tr><td colspan="10" class="empty">لا نتائج. جرّب اسمًا أو سعرًا مختلفًا.</td></tr>'}</tbody></table></div><div class="pagination"><button class="button small" data-action="prev-players" ${f.page<=1?'disabled':''}>السابق</button><span>${f.page} / ${pages}</span><button class="button small" data-action="next-players" ${f.page>=pages?'disabled':''}>التالي</button></div><div class="table-footer"><span>معدلات xG وxA تمزج آخر 5 مباريات بالموسم لتقليل أثر العينات الصغيرة. الملكية عامة؛ ملكية النخبة غير متصلة.</span>${fdrLegend()}</div></section>`;}
function transfersView(){const ideas=transferIdeas(squad(),players,bank(),settings.isNew?{}:settings.purchases,settings.isNew?5:n(settings.ft));return `${heading('كل نقلة، لها سبب.','بدائل قابلة للتمويل، مع مقارنة النقاط خلال الجولات الثلاث المقبلة.',`<a class="button" href="#settings">${icon('settings',14)} تعديل الرصيد</a>`)}${settings.isNew?'<div class="notice mb">أنت في وضع إنشاء فريق جديد؛ لا توجد تكلفة نقاط لاختياراتك الأولى. هذه المقارنات تساعدك على تحسين المسودة.</div>':''}<div class="stats-grid"><div class="stat-card"><div class="stat-head">البنك</div><div class="stat-value num">${money(bank())}</div></div><div class="stat-card"><div class="stat-head">النقلات الحرة المسجلة</div><div class="stat-value num">${settings.ft}</div></div><div class="stat-card"><div class="stat-head">تكلفة النقلة الإضافية</div><div class="stat-value num">${settings.isNew?'0':'−4'}</div></div><div class="stat-card"><div class="stat-head">أفق المقارنة</div><div class="stat-value">3 <span class="unit">جولات</span></div></div></div><section class="panel"><div class="panel-head"><div><h2>أولويات التحسين</h2><p>كل اقتراح نقلة مستقلة. يعاد الحساب بعد تطبيق أي تغيير.</p></div><span class="pill green-pill">قابلة للتمويل</span></div>${ideas.length?ideas.map(t=>`<div class="transfer-card"><div class="transfer-pair"><div class="transfer-person"><span class="tiny red">خروج</span>${playerCell(t.out)}<span class="tiny muted">بيع ${money(t.sale)}</span></div><span class="transfer-arrow">${icon('arrow',20)}</span><div class="transfer-person"><span class="tiny green">دخول</span>${playerCell(t.in)}<span class="tiny muted">شراء ${money(t.in.now_cost)}</span></div></div><div class="transfer-gain"><strong>+${fmt(t.gain)}</strong><span>فرق متوقع / 3 جولات</span>${!settings.isNew&&t.hit?`<div class="tiny yellow">بعد خصم 4: ${fmt(t.netGain)}</div>`:''}</div><button class="button ${t.netGain>0?'primary':''}" data-action="apply-transfer" data-out="${t.out.id}" data-in="${t.in.id}">تطبيق على المسودة</button></div>`).join(''):'<div class="empty">لا توجد نقلة فردية ترفع التوقعات ضمن رصيدك الحالي. الاحتفاظ بالنقلة خيار جيد.</div>'}<div class="table-footer">التوقع لا يضمن مكسبًا. بعد تفعيل نقلة محليًا، نفّذها بنفسك داخل FPL إذا اعتمدت القرار.</div></section><div class="notice warn mt">توقيت النقلة: انتظر المؤتمرات وأخبار الإصابات. صافي النقلات المعروض يخص الجولة، ولا يمثل تدفقًا يوميًا أو توقعًا مضمونًا للأسعار.</div>`;}
function fixturesView(){const teams=data.teams.map(t=>({...t,avg:Array.from({length:5},(_,i)=>fixturesFor(data,t.id,n(settings.gw)+i).map(f=>opponent(data,f,t.id).fdr)).flat()})).map(t=>({...t,mean:t.avg.reduce((a,b)=>a+b,0)/Math.max(1,t.avg.length)})).sort((a,b)=>a.mean-b.mean);return `${heading('انظر إلى ما بعد الجولة.','خمس جولات تساعدك على التخطيط للشراء، الدكة، والرقاقات.',`<a href="#settings" class="button">${icon('calendar',14)} بدءًا من الجولة ${settings.gw}</a>`)}<section class="panel"><div class="panel-head"><h2>خريطة المباريات</h2>${fdrLegend()}</div><div class="table-wrap"><table><thead><tr><th>النادي</th>${Array.from({length:5},(_,i)=>`<th>GW ${n(settings.gw)+i}</th>`).join('')}<th>متوسط FDR</th></tr></thead><tbody>${teams.map(t=>`<tr><td><strong>${esc(t.name)}</strong><br><span class="tiny muted num">${t.short_name}</span></td>${Array.from({length:5},(_,i)=>{const fs=fixturesFor(data,t.id,n(settings.gw)+i);return `<td>${fs.length?fs.map(f=>{const op=opponent(data,f,t.id);return `<div class="inline-flex" style="margin-bottom:3px"><span class="fixture-tag fdr${op.fdr}">${op.team.short_name} (${op.home?'H':'A'})</span><span class="tiny muted">${dateText(f.kickoff_time,false)}</span></div>`;}).join(''):'<span class="pill warn-pill">بلا مباراة</span>'}</td>`;}).join('')}<td class="metric">${fmt(t.mean)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer">FDR من FPL الرسمي، من 1 (أسهل) إلى 5 (أصعب). H: على الأرض، A: خارج الأرض. قد تتغير المواعيد.</div></section>`;}
function priceRows(count=6){const list=[...players].filter(p=>p.can_select!==false).sort((a,b)=>priceTab==='out'?a.net-b.net:b.net-a.net).slice(0,count);return list.map(p=>`<div class="price-row">${playerCell(p)}<div class="price-detail"><strong>${money(p.now_cost)}</strong><span class="num ${p.net>=0?'green':'red'}">${p.net>=0?'+':''}${fmt(p.net,0)}</span> <span class="muted tiny">صافي الجولة</span></div></div>`).join('');}
function pricesView(){const target=lineup().captain||players[0];return `${heading('ميزانيتك تلعب أيضًا.','راقب اتجاه الطلب واحسب قيمة البيع الفعلية قبل أي نقلة.')}<div class="two-column"><section class="panel"><div class="panel-head"><h2>حركة سوق الانتقالات</h2><div class="segmented"><button data-action="price-in" class="${priceTab==='in'?'active':''}">شراء</button><button data-action="price-out" class="${priceTab==='out'?'active':''}">بيع</button></div></div><div class="panel-body">${priceRows(10)}<div class="notice warn mt">المتاح هو صافي نقلات الجولة من FPL، وليس عدد نقلات آخر 24 ساعة. خوارزمية تغيير السعر غير معلنة؛ هذه إشارات طلب وليست مواعيد أو احتمالات مؤكدة للارتفاع.</div></div></section><div class="stack"><section class="panel"><div class="panel-head"><h2>حاسبة أرباح البيع</h2>${icon('wallet',18)}</div><div class="panel-body"><form id="sale-form" class="form-grid"><label class="form-field">سعر الشراء (£m)<input id="sale-buy" name="buy" type="number" min="3" max="30" step="0.1" value="${(settings.purchases[target.id]??target.now_cost)/10}" required></label><label class="form-field">السعر الحالي (£m)<input id="sale-current" name="current" type="number" min="3" max="30" step="0.1" value="${target.now_cost/10}" required></label><button class="button primary form-field full">احسب قيمة البيع</button></form><div id="sale-result" class="notice mt">يرجع لك £0.1m من كل زيادة £0.2m فوق سعر الشراء. يُحتسب الهبوط كاملًا.</div></div></section><section class="panel"><div class="panel-head"><h2>أسعار شراء فريقك</h2></div><div class="panel-body"><p class="help mb">سجّل سعر الشراء الحقيقي لحساب البدائل. الاستيراد العام لا يكشف أسعار شراء فريقك.</p><form id="purchases-form" class="form-grid">${squad().map(p=>`<label class="form-field">${esc(p.web_name)}<input type="number" min="3" max="30" step="0.1" name="${p.id}" value="${(settings.purchases[p.id]??p.now_cost)/10}" required></label>`).join('')}<button class="button primary form-field full">حفظ أسعار الشراء</button></form></div></section></div></div>`;}
function chipsView(){const tips=chipAdvice(data,squad(),n(settings.gw),settings.isNew,settings.chips);return `${heading('الرقاقة المناسبة. في الجولة المناسبة.','خطة مرتبطة بفريقك وبالجدول الرسمي المتاح، وتُراجع مع تغير المباريات.')}<div class="notice mb">${settings.isNew?'ابدأ بتكوين فريقك مجانًا؛ احتفظ بالرقاقات للجولات التي تمنحك فائدة إضافية.':'حدد الرقاقات التي لم تستخدمها. نوافذ الإتاحة مأخوذة من بيانات الموسم الحالي.'}</div><div class="chip-grid">${tips.map(c=>`<section class="panel chip-card"><div class="chip-top"><span class="green">${icon('chip',28)}</span><span class="pill ${c.available?'green-pill':''}">${c.status}</span></div><h2>${c.name}</h2><p>${c.advice}</p>${c.stop?`<div class="window">نافذة الموسم الحالية تنتهي في الجولة ${c.stop}</div>`:''}<label class="toggle mt"><input type="checkbox" data-chip="${c.key}" ${settings.chips[c.key]!==false?'checked':''}> لم أستخدمها في النافذة الحالية</label></section>`).join('')}</div><section class="panel section-gap"><div class="panel-head"><h2>مؤشرات الجدول لفريقك</h2></div><div class="panel-body"><div class="horizon-bar">${Array.from({length:5},(_,i)=>{const gw=n(settings.gw)+i,blank=squad().filter(p=>!fixturesFor(data,p.team,gw).length).length,double=squad().filter(p=>fixturesFor(data,p.team,gw).length>1).length;return `<div class="horizon-cell"><small>GW ${gw}</small><strong>${blank}</strong><small>لاعب بلا مباراة</small><span class="tiny teal">${double} لاعب بجولة مزدوجة</span></div>`;}).join('')}</div><p class="help mt">المباريات المؤجلة غير المجدولة لا تُعامل كجولات مزدوجة مؤكدة. توصيات الرقاقات تتطلب مراجعة نهائية للإصابات والدقائق.</p></div></section>`;}
function advisorView(){if(!chat.length)chat.push({role:'assistant',text:`أهلًا بك في مَدار. خطتك تبدأ من الجولة ${settings.gw} بميزانية ${money(settings.budget)}.\nأستطيع تفسير اختيارات فريقك، مقارنة اللاعبين، واقتراح الكابتن والنقلات والرقاقات.\nابدأ بسؤال مثل: «من أكبتن؟» أو اكتب اسم لاعب بالإنجليزية لتحليل أرقامه.`});return `${heading('لديك سؤال. لدينا الأرقام.','مساعد تحليلي يستند إلى بيانات فريقك، مع أسباب واضحة لكل قرار.')}<div class="chat-shell"><section class="panel chat-panel"><div class="panel-head"><div class="inline-flex"><span class="green">${icon('spark',22)}</span><div><h2>مساعد مَدار</h2><p>إجابات حسابية مرتبطة بالتشكيلة الحالية</p></div></div><span class="pill green-pill">الجولة ${settings.gw}</span></div><div class="chat-messages" id="chat-messages" aria-live="polite">${chat.map(m=>`<div class="chat-message ${m.role==='user'?'user':''}"><span class="chat-avatar">${icon(m.role==='user'?'users':'spark',16)}</span><div class="chat-bubble">${esc(m.text)}</div></div>`).join('')}</div><form id="chat-form" class="chat-form"><input name="message" aria-label="سؤالك للمساعد" placeholder="اسأل عن الكابتن، الانتقالات، أو اكتب اسم لاعب…" maxlength="500" required autocomplete="off"><button aria-label="إرسال السؤال">${icon('send',18)}</button></form></section><div class="stack chat-sidebar"><section class="panel"><div class="panel-head"><h2>ابدأ من هنا</h2></div><div class="panel-body quick-prompts">${['من أكبتن في هذه الجولة؟','حلل نقاط ضعف تشكيلتي','ما أفضل نقلة متاحة؟','متى أستخدم الرقاقات؟','كيف أحافظ على الميزانية؟','كيف أبدأ من الصفر؟'].map(q=>`<button data-question="${q}">${q} ${icon('arrow',12)}</button>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>ما الذي يقرأه مَدار؟</h2></div><div class="panel-body"><ul class="checklist"><li>${icon('check',13)} xG وxA ودقائق آخر المباريات</li><li>${icon('check',13)} قوة الخصم وفرص الشباك النظيفة</li><li>${icon('check',13)} ميزانيتك والملكية العامة</li><li>${icon('check',13)} جدول خمس جولات ونوافذ الرقاقات</li></ul><p class="help mt">محرك قواعد ونموذج نقاط شفاف. لا يستخدم نموذج محادثة لغويًا، ولا يقرأ أخبارًا صحفية خارج تحديثات FPL.</p></div></section></div></div>`;}
function answer(question){
 const q=question.toLowerCase(),s=squad(),l=lineup();const found=players.filter(p=>[p.web_name,p.known_name,`${p.first_name} ${p.second_name}`].some(name=>name&&name.length>2&&q.includes(name.toLowerCase()))).sort((a,b)=>b.minutes-a.minutes)[0];
 if(found){const p=found,r=p.recent;return `${p.web_name} · ${POS[p.element_type]} · ${money(p.now_cost)}\n${r.window}: xG ${fmt(r.xg,2)}، xA ${fmt(r.xa,2)}، xGI ${fmt(r.xg+r.xa,2)}. سجّل ${r.goals} وصنع ${r.assists}.\nxGI/90 المعدّل: ${fmt(r.xg90+r.xa90,2)}. متوسط الدقائق: ${fmt(r.avgMinutes,0)}.\nالجولة ${settings.gw}: ${fixtureLabel(p)}؛ ${fmt(p.xp)} نقطة متوقعة قبل مضاعفة الكابتن.\n${p.element_type<=2?`xGC في النافذة: ${fmt(r.xgc,2)}، واحتمال الشباك النظيفة من نموذج بواسون لأول مباراة: ${p.cs===null?'لا مباراة':fmt(p.cs*100,0)+'%'}.\n`:''}الملكية العامة: ${fmt(p.selected_by_percent)}%. صافي نقلات الجولة: ${p.net>=0?'+':''}${fmt(p.net,0)}.\n${p.news?`تحديث FPL: ${p.news}`:p.chance<1?'راجع الجاهزية قبل الشراء.':'متاح حسب آخر تحديث؛ راجع المؤتمر قبل الإغلاق.'}`;}
 if(/كابت|أكبت|اكبت|قائد|captain/.test(q)){const p=l.captain;return p?`الكابتن المقترح: ${p.web_name}. النائب: ${l.vice?.web_name}.\nتوقع ${fmt(p.xp)} نقطة (${fmt(p.xp*2)} بعد المضاعفة) ضد ${fixtureLabel(p)}.\nمعدله المعدّل xGI/90 هو ${fmt(p.recent.xg90+p.recent.xa90,2)} ومتوسطه ${fmt(p.recent.avgMinutes,0)} دقيقة. اختير لأعلى مساهمة هجومية متوقعة بين أساسييك الموثوقين بالدقائق.\nالترشيح مشروط باستمرار جاهزيته؛ تحقق من الأخبار قبل الإغلاق.`:'ابنِ تشكيلتك أولًا لأختار كابتن ونائبًا من لاعبيك.';}
 if(/رقاق|وايلد|chip|wildcard|تربل|بنشت/.test(q))return chipAdvice(data,s,n(settings.gw),settings.isNew,settings.chips).map(c=>`${c.name}: ${c.advice}${c.stop?` نافذتها الحالية حتى GW${c.stop}.`:''}`).join('\n\n');
 if(/نقل|بديل|انتقال|transfer|اشتري/.test(q)){const t=transferIdeas(s,players,bank(),settings.isNew?{}:settings.purchases,settings.isNew?5:n(settings.ft))[0];return t?`أفضل تحسين فردي وفق النموذج: ${t.out.web_name} ← ${t.in.web_name}.\nبيع ${money(t.sale)} وشراء ${money(t.in.now_cost)}؛ البنك بعدها ${money(t.bank)}.\nفرق متوقع +${fmt(t.gain)} نقطة عبر 3 جولات${!settings.isNew&&t.hit?`، والصافي بعد خصم 4 نقاط ${fmt(t.netGain)}`:''}.\n${settings.isNew?'أنت في وضع التأسيس؛ تعديل تشكيلتك الأولى لا يخصم نقاطًا.':'قارن المكسب المتوقع بتكلفة النقلة. الاحتفاظ بالنقلة قد يكون أفضل إذا كان الفارق صغيرًا.'}\nانتظر أخبار الإصابات ما لم تكن الميزانية ستمنع الصفقة.`:'لا أرى نقلة فردية ترفع توقعاتك ضمن الرصيد الحالي. الاحتفاظ بالنقلة خيار مقبول.';}
 if(/سعر|سعار|ميزان|budget|price|بيع/.test(q))return `البنك المتاح: ${money(bank())}. قيمة التشكيلة الحالية: ${money(s.reduce((a,p)=>a+p.now_cost,0))}.\nقيمة البيع = سعر الشراء + نصف الربح مقربًا لأسفل إلى أقرب £0.1m. إذا انخفض السعر، يُحتسب الانخفاض كاملًا.\nمثال: الشراء £5.0m والسعر الحالي £5.3m يعطي بيعًا £5.1m.\nصافي نقلات الجولة هو مؤشر طلب، ولا يحدد موعد ارتفاع السعر. سجّل أسعار الشراء في صفحة الأسعار لحساب البدائل بدقة.`;
 if(/ضعف|تشكيل|فريق|تحليل|حلل|squad/.test(q)){const weak=[...s].sort((a,b)=>a.score-b.score).slice(0,3);return s.length?`توقع الأساسيين والكابتن: ${fmt(l.points)} نقطة، بتشكيل ${l.formation}.\nأقل توقعات في فريقك: ${weak.map(p=>`${p.web_name} (${fmt(p.xp)})`).join('، ')}. قد يكون بعضهم بديلًا اقتصاديًا مناسبًا، وليس أولوية بيع تلقائية.\n${s.filter(p=>p.chance<1).length?`علامات جاهزية لدى: ${s.filter(p=>p.chance<1).map(p=>p.web_name).join('، ')}.`:'لا توجد علامة غياب لدى لاعبيك حسب تحديث FPL.'}\nلتحليل لاعب بعينه، اكتب اسمه بالإنجليزية.`:'ابدأ ببناء 15 لاعبًا من صفحة تشكيلتي؛ سأراجع التوازن والدقائق والميزانية.';}
 if(/موعد|متى|deadline|اغلاق|إغلاق/.test(q))return `موعد إغلاق الجولة ${settings.gw}: ${dateText(currentEvent()?.deadline_time)} بتوقيت UTC+3.\nراجع الأخبار ثم ثبت الأساسيين والكابتن والنائب والدكة في حساب FPL قبل الموعد.`;
 if(/صفر|ابدأ|أبدأ|بدا|جديد/.test(q))return `1. أنشئ حسابك في fantasy.premierleague.com.\n2. ابدأ بميزانية £100m واختر 15 لاعبًا: 2 حراس، 5 دفاع، 5 وسط، 3 هجوم، بحد أقصى 3 من كل نادٍ.\n3. استخدم «ابنِ فريقي» ثم راجع الأخبار وغيّر أي خيار لا يناسب رؤيتك.\n4. انقل اختياراتك إلى FPL وحدّد الأساسيين والكابتن والنائب.\nتكوين الفريق الأول مجاني. بدءك في الجولة ${settings.gw} لا يمنحك نقاط الجولات السابقة.`;
 if(/xg|xa|إحصا|احصا|متوقع/.test(q))return 'xG يقيس جودة فرص التسديد، وxA جودة صناعة الفرص. مجموعهما xGI.\nمقارنة الأهداف الفعلية والمتوقعة تكشف الفارق، لكنها لا تثبت أن اللاعب محظوظ أو سيعوضه تلقائيًا.\nنمزج معدلات آخر 5 مباريات بالموسم، ثم نعدّلها بالدقائق والخصم. xGC والشباك النظيفة تقديرات دفاعية، وليست ضمانًا. اكتب اسم لاعب لرؤية أرقامه.';
 return `يمكنني تحليل الكابتن، التشكيلة، النقلات، الرقاقات، والميزانية. اكتب اسم لاعب بالإنجليزية للحصول على xG وxA ودقائقه ومبارياته.\nالأسئلة المفتوحة والأخبار خارج FPL تحتاج مصدرًا إضافيًا؛ المحرك الحالي يجيب ضمن البيانات المتاحة فقط.`;
}
function settingsView(){return `${heading('اضبط الخطة على مقاسك.','نحتفظ بإعداداتك وتشكيلتك في هذا المتصفح، ويمكنك تنزيل نسخة منها.')}<section class="panel install-card"><div><h2>مَدار على Windows وAndroid</h2><p>نسخة Windows محمولة دون أدوات إضافية، أو تثبيت التطبيق من المتصفح على Android.</p></div><div class="install-card-actions"><a class="button primary" href="https://github.com/muohmd206-debug/fpl-madar-advisor/releases/latest/download/Madar-Windows-x64.zip">${icon('download',14)} تنزيل Windows</a><button class="button" data-action="install">تثبيت على جهازي</button></div></section><div class="two-column"><section class="panel"><div class="panel-head"><h2>ملف المدرب</h2></div><div class="panel-body"><form id="settings-form" class="form-grid"><label class="form-field">نوع البداية<select name="isNew"><option value="yes" ${settings.isNew?'selected':''}>فريق جديد من الصفر</option><option value="no" ${!settings.isNew?'selected':''}>إدارة فريق موجود</option></select></label><label class="form-field">الجولة المستهدفة<select name="gw">${gwOptions()}</select></label><label class="form-field">ميزانية التشكيلة (£m)<input name="budget" type="number" min="65" max="200" step="0.1" value="${settings.budget/10}" required></label><label class="form-field">البنك لفريق موجود (£m)<input name="bank" type="number" min="0" max="100" step="0.1" value="${settings.bank/10}" required></label><label class="form-field">النقلات الحرة<input name="ft" type="number" min="0" max="5" step="1" value="${settings.ft}" required></label><label class="form-field">أسلوب اللعب<select name="risk">${riskOptions()}</select></label><label class="form-field full">ترتيبك الحالي أو هدفك<input name="goal" maxlength="100" value="${esc(settings.goal)}" placeholder="مثال: تحسين ترتيبي أو منافسة الأصدقاء"></label><button class="button primary form-field full">حفظ الإعدادات</button></form></div></section><div class="stack"><section class="panel"><div class="panel-head"><h2>استيراد فريق موجود</h2>${icon('link',17)}</div><div class="panel-body"><form id="import-form" class="form-grid"><label class="form-field full">رقم فريق FPL العام (Team ID)<input name="entry" type="number" min="1" max="99999999" placeholder="مثال: 123456" required></label><button class="button form-field full">استيراد آخر تشكيلة منشورة</button></form><p class="help mt">تجد الرقم في رابط صفحة Points. لا نحتاج كلمة مرورك. الاستيراد يستخدم آخر جولة لها تشكيلة منشورة؛ النقلات اللاحقة وأسعار الشراء والنقلات الحرة قد تحتاج تحديثًا يدويًا.</p></div></section><section class="panel"><div class="panel-head"><h2>بياناتك وخطتك</h2></div><div class="panel-body"><div class="settings-actions"><button class="button" data-action="export">${icon('download',14)} تنزيل الخطة</button><label class="button">${icon('plus',14)} رفع خطة محفوظة<input id="restore-file" type="file" accept="application/json,.json" class="sr-only"></label></div><p class="help mt">الحفظ محلي في المتصفح. تنزيل الخطة يساعدك على نقلها إلى جهاز آخر. لا ينفذ التطبيق نقلات داخل حساب FPL.</p></div></section><section class="panel"><div class="panel-head"><h2>حالة البيانات</h2><span class="pill ${data.meta.live?'green-pill':'warn-pill'}">${data.meta.live?'متصل':'محفوظة'}</span></div><div class="panel-body source-list"><div class="source-item"><span class="muted">بيانات اللاعبين والجدول</span><span>${dateText(data.meta.fetchedAt)}</span></div><div class="source-item"><span class="muted">سجل المباريات المحفوظ</span><span>${dateText(data.meta.historyFetchedAt)}</span></div><div class="source-item"><span class="muted">سجل تفصيلي للاعبين</span><span class="num">${Object.keys(data.histories||{}).length}</span></div><button class="button" data-action="refresh" ${refreshing?'disabled':''}>${icon('refresh',14)} تحديث البيانات</button><p class="help">المواعيد المعروضة بتوقيت UTC+3. التحديث المباشر يجلب اللاعبين والجدول. نحدّث سجلات الفريق والمرشحين تلقائيًا بعد مرور 3 ساعات، ونحدّث سجل أي لاعب عند فتحه. نبيّن ما تعذر تحديثه.</p></div></section></div></div>`;}
function methodView(){return `${heading('الأرقام واضحة. وكذلك المنهجية.','اعرف ما يقيسه مَدار، وما الذي يحتاج إلى حكمك كمدرب.')}<div class="definition-grid">${[['xG','جودة الفرص التي يسددها اللاعب، قبل معرفة النتيجة.'],['xA','جودة التمريرات التي تصنع فرصًا للتسجيل.'],['xGI','مجموع xG وxA، مؤشر للمساهمة الهجومية.'],['xGC','الأهداف المتوقعة المستقبلة أثناء وجود اللاعب في الملعب.'],['xPts','نقاط يقدّرها نموذج مَدار؛ ليست توقع FPL الرسمي.'],['FDR','تقييم FPL لصعوبة المباراة من 1 إلى 5.']].map(([k,v])=>`<div class="definition"><strong class="num">${k}</strong><p>${v}</p></div>`).join('')}</div><div class="two-column section-gap"><section class="panel"><div class="panel-head"><h2>كيف تتكون التوصية؟</h2></div><div class="panel-body"><ol class="method-list"><li>نقرأ أسعار اللاعبين، مراكزهم، الجاهزية، الإحصاءات والجدول من FPL الرسمي.</li><li>نستخدم آخر 5 مباريات متاحة قبل الجولة، ونمزج معدلاتها لكل 90 دقيقة بمعدلات الموسم. وزن العينة الأخيرة يرتفع مع دقائقها حتى 70%.</li><li>نقدّر دقائق المشاركة من متوسط المباريات المتاحة، ثم نطبق مؤشر الجاهزية المنشور في FPL.</li><li>نعدّل المساهمة الهجومية بمعامل FDR (1: 1.25، 2: 1.12، 3: 1، 4: 0.84، 5: 0.70) ومعامل الأرض 1.04 أو خارجها 0.96.</li><li>نقدّر الشباك النظيفة عبر بواسون: exp(−λ). يمزج λ متوسط xGC لمجموعة الأكثر دقائق في الفريق مع قوة هجوم الخصم ومكان المباراة. هذه احتمالات نموذجية، وليست أسعار مراهنات.</li><li>نضيف تقديرات الظهور، التسجيل والصناعة، الشباك النظيفة، التصديات، المساهمة الدفاعية والبونص، ونطرح تقديرًا للبطاقات والأهداف المستقبلة. البونص والتصديات تقريبان من المعدلات وليسا محاكاة كاملة لنظام BPS.</li><li>نعطي وزنًا متساويًا للجولة الحالية ومتوسط الجولات الخمس، ثم نختار تشكيلة صالحة بالبحث عن تحسينات ضمن الميزانية. لا ندّعي إيجاد الحل الأمثل رياضيًا.</li><li>نختار الأساسيين ضمن التشكيلات القانونية. نرتب خيارات الكابتن بحسب xGI المتوقع المعدّل بالخصم والدقائق، بين من يبلغ متوسطهم 60 دقيقة على الأقل وجاهزيتهم 75% على الأقل. نحتسب مضاعفة الكابتن في إجمالي الفريق.</li></ol></div></section><div class="stack"><section class="panel"><div class="panel-head"><h2>مصادر وحدود البيانات</h2></div><div class="panel-body"><ul class="method-list"><li>الملكية المعروضة عامة. لا تتوفر حاليًا ملكية النخبة أو الملكية الفعالة.</li><li>صافي النقلات يخص الجولة، وليس آخر 24 ساعة. تغير السعر بمقدار £0.1m لا يمكن ضمانه من هذه الأرقام.</li><li>الدقائق والإصابات قد تتغير بعد تحديث البيانات. أخبار التطبيق هي ما ينشره FPL فقط.</li><li>إذا تعذر الاتصال، نعرض نسخة محفوظة مؤرخة ونوضح ذلك.</li><li>المساعد محرك قواعد حسابية، ولا يستخدم نموذج لغة أو متابعة صحفية مستقلة.</li></ul></div></section><section class="panel"><div class="panel-head"><h2>المراجع الرسمية</h2></div><div class="panel-body source-list"><a class="text-link" target="_blank" rel="noopener" href="https://fantasy.premierleague.com/api/bootstrap-static/">بيانات اللاعبين واللعبة ${icon('link',13)}</a><a class="text-link" target="_blank" rel="noopener" href="https://fantasy.premierleague.com/api/fixtures/">جدول المباريات ${icon('link',13)}</a><a class="text-link" target="_blank" rel="noopener" href="https://fantasy.premierleague.com/help/rules">قواعد FPL ${icon('link',13)}</a></div></section></div></div>`;}

async function generate(){if(busy)return;busy=true;render();try{const result=await new Promise((resolve,reject)=>{const worker=new Worker('/optimizer.js',{type:'module'});const timeout=setTimeout(()=>{worker.terminate();reject(new Error('استغرق اختيار الفريق وقتًا طويلًا؛ حاول مرة أخرى.'));},45000);worker.onmessage=e=>{clearTimeout(timeout);worker.terminate();e.data.error?reject(new Error(e.data.error)):resolve(e.data.ids);};worker.onerror=()=>{clearTimeout(timeout);worker.terminate();reject(new Error('تعذر تشغيل محرك الاختيار في المتصفح. أعد تحميل الصفحة.'));};worker.postMessage({players,budget:settings.budget});});squadIds=result;for(const p of squad())settings.purchases[p.id]=p.now_cost;if(!settings.isNew)settings.bank=settings.budget-squad().reduce((s,p)=>s+p.now_cost,0);persist();toast('تشكيلتك جاهزة للمراجعة. اختياراتك محفوظة في هذا المتصفح.');}catch(e){toast(e.message);}finally{busy=false;render();}}
async function refresh(){if(refreshing)return;refreshing=true;render();try{const response=await fetch('/api/data?refresh=1');if(!response.ok)throw new Error('تعذر الاتصال بالبيانات الرسمية.');const fresh=await response.json();data=fresh;let failed=0;if(squadIds.length){const results=await Promise.allSettled(squadIds.map(async id=>{const r=await fetch(`/api/history/${id}`);if(!r.ok)throw new Error();return [id,(await r.json()).history];}));for(const result of results)if(result.status==='fulfilled'){data.histories[result.value[0]]=result.value[1];historyTimes[result.value[0]]=Date.now();}else failed++;data.meta.squadHistoryUpdated=failed===0;}recompute();persist();toast(!fresh.meta.live?'تعذر التحديث المباشر؛ نعرض النسخة المحفوظة المؤرخة.':failed?'تحدثت البيانات العامة. تعذر تحديث سجل بعض لاعبي الفريق.':'تم تحديث بيانات اللاعبين والجدول وسجل لاعبي فريقك.');}catch(e){toast(e.message);}finally{refreshing=false;render();}}
function closeModal(){openPlayerId=null;$('#modal-root').innerHTML='';document.body.style.overflow='';}
let modalReturn=null;
function showModal(html){modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="تفاصيل اللاعب">${html}</section></div>`;document.body.style.overflow='hidden';$('#modal-root button')?.focus();}
async function playerModal(id){const p=players.find(p=>p.id===n(id));if(!p)return;openPlayerId=p.id;const r=p.recent;const diff=r.goals+r.assists-r.xg-r.xa;const owned=squadIds.includes(p.id);const swapOptions=squad().filter(o=>o.element_type===p.element_type&&o.id!==p.id);const max=Math.max(.1,...r.history.map(h=>n(h.expected_goals)+n(h.expected_assists)));showModal(`<div class="modal-header"><div><h2>${esc(p.web_name)}</h2><p>${esc(team(p).name)} · ${POS[p.element_type]} · <span class="num">${money(p.now_cost)}</span></p></div><button class="icon-button" data-action="close-modal" aria-label="إغلاق">${icon('close',17)}</button></div>${p.news?`<div class="notice warn mb">${esc(p.news)}</div>`:''}<div class="modal-stats"><div class="modal-stat"><strong class="green">${fmt(p.xp)}</strong><span>نقاط الجولة المتوقعة</span></div><div class="modal-stat"><strong>${fmt(r.xg,2)}</strong><span>xG · ${r.window}</span></div><div class="modal-stat"><strong>${fmt(r.xa,2)}</strong><span>xA · ${r.window}</span></div><div class="modal-stat"><strong>${fmt(r.xg+r.xa,2)}</strong><span>xGI · ${r.window}</span></div></div><section class="panel"><div class="panel-head"><h2>المساهمة الهجومية المتوقعة</h2><span class="tiny muted">${r.window}</span></div>${r.history.length?`<div class="chart-area">${r.history.map(h=>`<div class="chart-col"><div class="chart-bars"><div class="chart-bar" style="height:${Math.max(3,n(h.expected_goals)/max*95)}px"><span>${fmt(h.expected_goals,2)}</span></div><div class="chart-bar xa-bar" style="height:${Math.max(3,n(h.expected_assists)/max*95)}px"><span>${fmt(h.expected_assists,2)}</span></div></div><small>GW ${h.round}</small></div>`).join('')}</div><div class="panel-body"><span class="tiny green">■ xG</span> &nbsp; <span class="tiny teal">■ xA</span></div>`:'<div class="empty">لا يتوفر سجل مفصل محفوظ لهذا اللاعب؛ الأرقام المعروضة من الموسم.</div>'}</section><div class="form-grid mt"><div class="notice">سجّل وصنع <span class="num">${r.goals+r.assists}</span> مقابل <span class="num">${fmt(r.xg+r.xa,2)}</span> متوقعة. الفارق <span class="num">${diff>=0?'+':''}${fmt(diff,2)}</span>، ولا يضمن اتجاه النتائج القادمة.</div><div class="notice">متوسط <span class="num">${fmt(r.avgMinutes,0)}</span> دقيقة، وبونص الموسم <span class="num">${p.bonus}</span>، وBPS <span class="num">${p.bps}</span>. الملكية العامة <span class="num">${fmt(p.selected_by_percent)}%</span>.</div></div>${p.element_type<=2?`<div class="notice mt">xGC في النافذة: <span class="num">${fmt(r.xgc,2)}</span>. تصديات الموسم: <span class="num">${p.saves}</span>. احتمال شباك نظيفة لأول مباراة: <span class="num">${p.cs===null?'—':fmt(p.cs*100,0)+'%'}</span> وفق نموذج مَدار.</div>`:''}<div class="mt mb">${fixtureRun(p)}</div>${owned?`<div class="inline-flex spread"><span class="pill green-pill">ضمن تشكيلتك</span><button class="button" data-action="swap" data-id="${p.id}">استكشف البدائل ${icon('arrows',14)}</button></div>`:swapOptions.length?`<form id="add-player-form" class="inline-flex"><input type="hidden" name="incoming" value="${p.id}"><select name="outgoing" aria-label="اللاعب المراد استبداله">${swapOptions.map(o=>`<option value="${o.id}">بدلاً من ${esc(o.web_name)}</option>`).join('')}</select><button class="button primary">أضف إلى المسودة</button></form>`:'<p class="help">ابنِ فريقك أولًا، ثم استبدل أحد لاعبيه بهذا الخيار.</p>'}<p class="help mt">تحديث السجل: ${dateText(historyTimes[p.id]||data.meta.historyFetchedAt)} (UTC+3). معدلات كل 90 دقيقة معدّلة بعينة الموسم.</p>`);if(data.meta.live){const result=await updateHistories([p.id]);if(result.changed&&openPlayerId===p.id){render();playerModal(p.id);}}}
function swapModal(id){const out=players.find(p=>p.id===n(id));if(!out)return;const sale=settings.isNew?out.now_cost:sellingPrice(settings.purchases[out.id]??out.now_cost,out.now_cost);const candidates=players.filter(p=>p.element_type===out.element_type&&!squadIds.includes(p.id)&&p.can_select!==false&&p.now_cost<=sale+bank()&&squad().filter(s=>s.team===p.team&&s.id!==out.id).length<3).sort((a,b)=>b.score-a.score).slice(0,20);showModal(`<div class="modal-header"><div><h2>بدائل ${esc(out.web_name)}</h2><p>الحد المتاح: ${money(sale+bank())} · نفس المركز، ضمن قيود فريقك</p></div><button class="icon-button" data-action="close-modal" aria-label="إغلاق">${icon('close',17)}</button></div><div class="swap-list">${candidates.map(p=>`<div class="swap-row">${playerCell(p)}<span class="num small">${money(p.now_cost)}</span><span class="metric-pill">${fmt(p.xp)}</span><button class="button small" data-action="apply-transfer" data-out="${out.id}" data-in="${p.id}">اختيار</button></div>`).join('')||'<div class="empty">لا بديل مناسب ضمن الرصيد المتاح.</div>'}</div>`);}
function applyTransfer(outId,inId){const out=players.find(p=>p.id===n(outId)),incoming=players.find(p=>p.id===n(inId));if(!out||!incoming||!squadIds.includes(out.id)||squadIds.includes(incoming.id))return;const sale=settings.isNew?out.now_cost:sellingPrice(settings.purchases[out.id]??out.now_cost,out.now_cost);if(incoming.element_type!==out.element_type||incoming.can_select===false||sale+bank()<incoming.now_cost){toast('الاختيار لا يطابق المركز أو يتجاوز رصيدك.');return;}if(squad().filter(p=>p.team===incoming.team&&p.id!==out.id).length>=3){toast('الحد الأقصى ثلاثة لاعبين من النادي نفسه.');return;}const newBank=bank()+sale-incoming.now_cost;squadIds=squadIds.map(id=>id===out.id?incoming.id:id);settings.purchases[incoming.id]=incoming.now_cost;if(!settings.isNew){settings.bank=newBank;settings.ft=Math.max(0,n(settings.ft)-1);}persist();closeModal();render();toast('تم التعديل على مسودتك فقط. لم تُنفذ نقلة في حساب FPL.');}
function sendChat(text){if(!text?.trim())return;chat.push({role:'user',text:text.trim()});chat.push({role:'assistant',text:answer(text)});if(chat.length>40)chat=chat.slice(-40);render();const box=$('#chat-messages');if(box)box.scrollTop=box.scrollHeight;$('#chat-form input')?.focus();}
function exportPlan(){const payload={app:'madar-fpl',version:1,exportedAt:new Date().toISOString(),settings,squad:squadIds,summary:squad().map(p=>({id:p.id,name:p.web_name,position:POS[p.element_type],price:p.now_cost,xPts:p.xp,fixtures:fixtureLabel(p)})),captain:lineup().captain?.id,viceCaptain:lineup().vice?.id,expectedPoints:lineup().points,dataUpdatedAt:data.meta.fetchedAt};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`madar-gw${settings.gw}-plan.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('تم تنزيل خطتك.');}

document.addEventListener('click',event=>{
 const q=event.target.closest('[data-question]');if(q){sendChat(q.dataset.question);return;}
 const player=event.target.closest('[data-player]');if(player){playerModal(player.dataset.player);return;}
 const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;
 if(action==='generate')generate();else if(action==='refresh')refresh();else if(action==='menu'){$('.sidebar').classList.add('open');$('.mobile-overlay').classList.add('show');}else if(action==='close-menu'){$('.sidebar').classList.remove('open');$('.mobile-overlay').classList.remove('show');}else if(action==='export')exportPlan();else if(action==='close-modal'||action==='backdrop'&&event.target===target){closeModal();modalReturn?.focus();}else if(action==='swap')swapModal(target.dataset.id);else if(action==='apply-transfer')applyTransfer(target.dataset.out,target.dataset.in);else if(action==='price-in'||action==='price-out'){priceTab=action==='price-in'?'in':'out';render();}else if(action==='prev-players'||action==='next-players'){playerFilter.page+=action==='prev-players'?-1:1;render();}
});
document.addEventListener('change',async event=>{
 const t=event.target;
 if(t.matches('[data-chip]')){settings.chips[t.dataset.chip]=t.checked;persist();render();}
 if(t.id==='player-pos'||t.id==='player-sort'||t.id==='player-max'){playerFilter[t.id==='player-pos'?'pos':t.id==='player-sort'?'sort':'max']=t.id==='player-sort'?t.value:n(t.value);playerFilter.page=1;render();}
 if(t.id==='restore-file'&&t.files[0])try{const restored=JSON.parse(await t.files[0].text());if(restored.app!=='madar-fpl'||restored.version!==1||!Array.isArray(restored.squad)||restored.squad.length!==15||new Set(restored.squad).size!==15||restored.squad.some(id=>!players.find(p=>p.id===id))||!restored.settings)throw new Error('ملف الخطة غير صالح أو ينتمي إلى بيانات موسم مختلف.');const rs=restored.settings;if(!Number.isFinite(rs.budget)||rs.budget<650||rs.budget>2000||!data.events.some(e=>e.id===n(rs.gw)))throw new Error('إعدادات الخطة غير صالحة.');const incoming=restored.squad.map(id=>players.find(p=>p.id===id));const invalid=validateSquad(incoming,Math.max(rs.budget,incoming.reduce((s,p)=>s+p.now_cost,0)));if(invalid.length)throw new Error(invalid.join('، '));settings={...settings,...rs,purchases:rs.purchases||{},chips:rs.chips||{}};squadIds=restored.squad;recompute();persist();render();toast('تم استرجاع خطتك. راجع الأسعار المحدثة قبل التنفيذ.');}catch(e){toast(e.message);}
});
document.addEventListener('input',event=>{if(event.target.id==='player-search'){const position=event.target.selectionStart;playerFilter.search=event.target.value;playerFilter.page=1;clearTimeout(playerFilter.timer);playerFilter.timer=setTimeout(()=>{render();const input=$('#player-search');input?.focus();input?.setSelectionRange(position,position);},180);}});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!['start-form','settings-form','chat-form','sale-form','purchases-form','import-form','add-player-form'].includes(form.id))return;event.preventDefault();const f=new FormData(form);
 if(form.id==='chat-form'){sendChat(f.get('message'));return;}
 if(form.id==='sale-form'){const buy=Math.round(n(f.get('buy'))*10),current=Math.round(n(f.get('current'))*10);$('#sale-result').innerHTML=`قيمة البيع الفعلية <strong class="num green">${money(sellingPrice(buy,current))}</strong> · الربح المحقق <strong class="num">${money(sellingPrice(buy,current)-buy)}</strong>.`;return;}
 if(form.id==='purchases-form'){for(const [k,v] of f)settings.purchases[n(k)]=Math.round(n(v)*10);persist();toast('تم حفظ أسعار الشراء وإعادة حساب قيمة البيع.');return;}
 if(form.id==='add-player-form'){applyTransfer(n(f.get('outgoing')),n(f.get('incoming')));return;}
 if(form.id==='start-form'||form.id==='settings-form'){
  const oldMode=settings.isNew;settings.budget=Math.round(n(f.get('budget'))*10);settings.gw=n(f.get('gw'));settings.risk=f.get('risk');
  if(form.id==='settings-form'){settings.isNew=f.get('isNew')==='yes';settings.ft=n(f.get('ft'));settings.bank=Math.round(n(f.get('bank'))*10);settings.goal=String(f.get('goal')).trim();if(oldMode&&!settings.isNew)for(const p of squad())settings.purchases[p.id]??=p.now_cost;}
  recompute();persist();render();if(form.id==='start-form')generate();else toast('تم حفظ إعداداتك. أعد بناء الفريق إذا غيّرت ميزانية التأسيس.');return;
 }
 if(form.id==='import-form'){
  const button=form.querySelector('button');button.disabled=true;button.textContent='جارٍ قراءة التشكيلة العامة…';
  try{const response=await fetch(`/api/entry/${n(f.get('entry'))}`);const result=await response.json();if(!response.ok)throw new Error(result.error||'تعذر استيراد الفريق.');const ids=result.picks.map(p=>p.element);if(ids.length!==15||ids.some(id=>!players.find(p=>p.id===id)))throw new Error('لم نتمكن من مطابقة 15 لاعبًا في البيانات الحالية.');squadIds=ids;settings.isNew=false;settings.bank=n(result.entry.last_deadline_bank);settings.budget=squad().reduce((s,p)=>s+p.now_cost,0)+settings.bank;settings.purchases={};for(const p of squad())settings.purchases[p.id]=p.now_cost;settings.goal=result.entry.summary_overall_rank?`الترتيب العام: ${fmt(result.entry.summary_overall_rank,0)}`:settings.goal;persist();render();toast(`تم استيراد تشكيلة الجولة ${result.event}. حدّث البنك وأسعار الشراء والنقلات الحرة يدويًا.`);}catch(e){toast(e.message);button.disabled=false;button.textContent='استيراد آخر تشكيلة منشورة';}
 }
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('#modal-root').children.length){closeModal();modalReturn?.focus();}if(event.key==='Tab'&&$('#modal-root').children.length){const nodes=[...$('#modal-root').querySelectorAll('button,a[href],input,select')].filter(e=>!e.disabled);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){last?.focus();event.preventDefault();}else if(!event.shiftKey&&document.activeElement===last){first?.focus();event.preventDefault();}}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'dashboard';closeModal();render();window.scrollTo(0,0);});
async function init(){try{const response=await fetch('/api/data');if(!response.ok)throw new Error('لم نتمكن من تحميل بيانات FPL.');data=await response.json();try{const cached=JSON.parse(localStorage.getItem('madar-history-v1')||'null');if(cached?.season===season())for(const [id,item] of Object.entries(cached.histories||{}))if(item.time>Date.parse(data.meta.historyFetchedAt)&&Array.isArray(item.history)){data.histories[id]=item.history;historyTimes[id]=item.time;}}catch{}if(!stored.settings&&nextEvent().id>11)settings.gw=nextEvent().id;recompute();render();if(squadIds.length!==15)await generate();if(data.meta.live){const shortlist=players.filter(p=>p.recent.avgMinutes>=45&&p.chance>=.75).sort((a,b)=>b.score-a.score).slice(0,45).map(p=>p.id);const result=await updateHistories([...squadIds,...shortlist]);if(result.changed){render();if(result.failures)toast('تحدث السجل المتاح؛ تعذر تحديث بعض اللاعبين. راجع تاريخ السجل في تفاصيل اللاعب.');}}}catch(e){$('#app').innerHTML=`<div class="error-screen"><div class="green">${icon('target',40)}</div><h1>نحتاج إلى استعادة الاتصال</h1><p>${esc(e.message)}</p><button class="button primary" id="retry-load">حاول مجددًا</button></div>`;$('#retry-load').addEventListener('click',()=>location.reload());}}
init();
